        $base+['name'=>'jg_describe_table','title'=>'Describe dashboard table','description'=>'Show exact typed columns, record grain, date basis and metric cautions before querying. Customer contacts, credentials and free-text notes are excluded. Datetime filters use UTC; _jakarta_day/_jakarta_month dimensions convert supported timestamp fields to Jakarta.','inputSchema'=>['type'=>'object','properties'=>['table'=>$table],'required'=>['table'],'additionalProperties'=>false]],
        $base+['name'=>'jg_query_table','title'=>'Query dashboard business data','description'=>'General typed rows or filtered/grouped aggregates. Discover and describe first. Use catalog filters volume+unit for all5ml products, flavor for allPlain sizes; group sales_lines by product/flavor/volume/unit/brand/channel. Explicit inclusive Jakarta dates required for semantic sales views, max366days. sales_orders.seller_revenue is recorded order revenue once; sales_lines.line_revenue is product-line revenue. Never sum dashboard_order_mirror.order_net_revenue. Money is decimal IDR strings. Stock, accounting, wallet, partner, ads and website tables expose stored records with explicit status/void filters. Customer activity aggregates are event counts, not identifiable or distinct customers. Paginate using next_offset; pages can change between calls. No arbitrary SQL, refresh or writes. Failed required sources return error, not zero. Consolidated stored channel records are not audited all-business revenue; synchronization/deduplication limitations must accompany totals.','inputSchema'=>['type'=>'object','properties'=>['table'=>$table,'columns'=>$arr($str),'filters'=>$arr($filter),'group_by'=>$arr($str),'metrics'=>$arr($metric),'order_by'=>$arr($order,10),'limit'=>['type'=>'integer','minimum'=>1,'maximum'=>200],'offset'=>['type'=>'integer','minimum'=>0,'maximum'=>100000],'start_date'=>['type'=>'string','pattern'=>'^\\d{4}-\\d{2}-\\d{2}$'],'end_date'=>['type'=>'string','pattern'=>'^\\d{4}-\\d{2}-\\d{2}$']],'required'=>['table'],'additionalProperties'=>false]],
        $base+['name'=>'jg_annualize_sales','title'=>'Annualize observed sales revenue','description'=>'Calculate monetary recorded seller-sales run rate for explicit YYYY-MM, across marketplace, paid website, direct/counter and partner sources. completed_days default returns insufficient_completed_history on the first day; elapsed_time explicitly includes the partial day. Never uses units or a single product as a monetary proxy. Returns actual observed IDR, cutoff, elapsed/year seconds and provenance. Mechanical run rate is not actual annual revenue, cash, profit, forecast or audited all-business revenue; report unverified sync and cross-channel duplication. All required sources must be available.','inputSchema'=>['type'=>'object','properties'=>['month'=>['type'=>'string','pattern'=>'^\\d{4}-(0[1-9]|1[0-2])$'],'basis'=>['type'=>'string','enum'=>['completed_days','elapsed_time']]],'required'=>['month'],'additionalProperties'=>false]]
